()=>{const list=FURYBOT.targetList;FURYBOT.targetList=function(){const all=list.call(this);if(bossActive||subBossActive){const structural=all.filter(t=>!/hostile missile|ordnance|enemy missile/i.test(t.kind||''));if(structural.length)return structural;}return all;};FURYBOT.events.push({t:FURYBOT.age(),type:'controller-policy',note:'Aim toward visible boss/module Retina markers before chasing interceptable missile markers at the screen edge; native weapons and damage unchanged.'});return{t:FURYBOT.age(),targets:FURYBOT.targetList().map(q=>({kind:q.kind,x:q.x,y:q.y,hp:q.hp})),stage:run.stage,sub:subBoss?{kind:subBoss.kind,hp:subBoss.hp,dead:subBoss.dead}:null,gateTaken:run._s9taken,resume:run._s5Resume?Object.keys(run._s5Resume):null};}
